using System.Text.Json;
using Cord.Core;

namespace Cord.Tests;

/// <summary>
/// Fixtures/ttn_mock.csv was generated by the Python cord's mock data generator, and
/// ttn_mock.python-result.json holds what the Python validator made of it.
/// The C# port must accept and reject the same rows.
/// </summary>
public class PythonParityTests
{
    private sealed record PythonResult(int Rows, int Valid, int[] InvalidRows, string[] Fields);

    [Fact]
    public void Accepts_and_rejects_the_same_rows_as_the_python_original()
    {
        var expected = JsonSerializer.Deserialize<PythonResult>(
            File.ReadAllText(SampleRows.Fixture("ttn_mock.python-result.json")), JsonSerializerOptions.Web)!;

        using var reader = File.OpenText(SampleRows.Fixture("ttn_mock.csv"));
        var result = WaybillValidation.Validate(new SourceFile("ttn_mock.csv", DelimitedFile.ReadRows(reader)));

        Assert.Equal(expected.Rows, result.Rows);
        Assert.Equal(expected.Valid, result.Waybills.Count);
        Assert.Equal(expected.InvalidRows, result.Errors.Select(e => e.Row).Distinct().Order());
        Assert.Equal(expected.Fields, result.Errors.Select(e => e.Field).Distinct().Order());
    }

    [Fact]
    public void Several_files_validate_as_one_stream_and_errors_keep_their_file()
    {
        var rows = File.ReadLines(SampleRows.Fixture("ttn_mock.csv")).Skip(1).Select(line => line.Split('^')).ToList();
        SourceFile[] files = [new("a.csv", rows[..10]), new("b.csv", rows[10..])];

        var result = WaybillValidation.Validate(files);

        Assert.Equal(40, result.Rows);
        Assert.Equal(32, result.Waybills.Count);
        Assert.Equal(["a.csv", "b.csv"], result.Errors.Select(e => e.File).Distinct());
        Assert.Contains(result.Errors, e => e is { File: "b.csv", Row: 9 }); // row 19 overall
    }
}
